  "command": "cat << 'PYEOF' > build_outline.py\nimport json\n\n# 读取现有的第一幕大纲\nwith open('outline.json', 'r', encoding='utf-8') as f:\n    outline = json.load(f)\n\n# 创建第二幕结构\nact_two = {\n    \"description\": \"第二幕：深入（约5.5万字，11章）- 穿越傈僳族村寨、发现父辈日记、遭遇商业势力阻挠、两人关系跌入谷底又和解\",\n    \"story_synopsis\": \"两人沿着新发现的路线深入横断山脉腹地。在村寨外围遇到马崇山派来的尾随者，秦北望设伏制服。进入傈僳族村寨领地后被阿依莫的巡逻队截住，秦北望拿出玉佩引发新的疑问。当夜两人爆发最严重冲突。老头人揭示真相后两人和解。高海拔路段沈屿森高原反应加剧，被格桑救助。三人到达望天崖发现父辈遗物和最后笔记，进入龙口古城入口。\",\n    \"key_chapters\": [],\n    \"turning_point\": \"在望天崖发现父辈的遗物和最后笔记，确认他们当年进入了龙口。笔记中对儿子们说的话让两人真正理解了父辈的选择。三人决定进入龙口，追寻父辈最后的足迹。\"\n}\n\n# 第7章\nch7 = {\n    \"chapter_number\": 7,\n    \"chapter_title\": \"尾随者\",\n    \"chapter_synopsis\": \"两人沿新路线深入，秦北望发现有人尾随（起始：警觉的行军状态）。他设伏制服尾随者，得知是马崇山派来的人（推进：外部势力介入）。审问出马崇山另有队伍从东边进山。两人决定加快速度（结束状态：外部压力增加）\",\n    \"scene_sequence\": [\n        {\"scene_number\": 1, \"scene_location\": \"密林中的隐蔽小道，清晨薄雾弥漫\", \"characters_present\": [\"秦北望\", \"沈屿森\"], \"scene_purpose\": \"展现秦北望侦察直觉，引出尾随者\", \"core_action\": \"秦北望蹲下检查地上脚印，发现除了他们的还有第三组登山靴印，方向一致时间很近，低声说有人跟了至少一天\", \"conflict_point\": \"沈屿森紧张询问是否村寨的人，秦北望判断是外人\", \"emotional_shift\": \"从正常行进的放松转为被跟踪的警觉\", \"scene_outcome\": \"秦北望让沈屿森继续走，自己绕后设伏\"},\n        {\"scene_number\": 2, \"scene_location\": \"山坳灌木丛，天光斑驳\", \"characters_present\": [\"秦北望\", \"马崇山的手下\"], \"scene_purpose\": \"动作场景展现秦北望战斗力\", \"core_action\": \"秦北望从后方锁住尾随者喉咙夺刀制服，搜出手机对讲机逼问派遣者\", \"conflict_point\": \"对方起初不说话，秦北望威胁用审俘老办法\", \"emotional_shift\": \"从设伏冷静转为审问时的愤怒\", \"scene_outcome\": \"对方交代是马崇山派来跟踪汇报位置\"},\n        {\"scene_number\": 3, \"scene_location\": \"同上，沈屿森赶回\", \"characters_present\": [\"秦北望\", \"沈屿森\", \"马崇山的手下\"], \"scene_purpose\": \"信息揭示交代马崇山计划\", \"core_action\": \"秦北望告诉沈屿森马崇山已组织另一支队伍从东边进山目标同样是古城\", \"conflict_point\": \"沈屿森愤怒那帮人只想商业开发不在乎考古价值\", \"emotional_shift\": \"从震惊转为危机驱动的决心\", \"scene_outcome\": \"两人缴装备绑人留食物后加速前进\"}\n    ],\n    \"emotional_tone\": \"紧张、外部威胁逼近\"\n}\nact_two[\"key_chapters\"].append(ch7)\n\n# 第8章\nch8 = {\n    \"chapter_number\": 8,\n    \"chapter_title\": \"村寨\",\n    \"chapter_synopsis\": \"两人进入傈僳族村寨领地被阿依莫巡逻队截住（起始：被武装村民包围）。阿依莫听到他们的身份后更加愤怒——二十年前的冲突仍是村寨伤疤（推进：历史恩怨浮现）。秦北望拿出玉佩，阿依莫认出是村寨圣物（结束状态：僵持被暂时扣押）\",\n    \"scene_sequence\": [\n        {\"scene_number\": 1, \"scene_location\": \"村寨外围山路，两侧陡峭山崖，灌木丛有人影\", \"characters_present\": [\"秦北望\", \"沈屿森\", \"阿依莫及村民\"], \"scene_purpose\": \"展现傈僳族村寨封闭性和敌意\", \"core_action\": \"两人走到狭窄山道时前后突然出现持刀村民，领头女人皮肤黝黑目光锐利用带口音普通话问他们来做什么\", \"conflict_point\": \"阿依莫听到秦守山和沈怀瑾的名字后脸色骤变\", \"emotional_shift\": \"从被包围的紧张转为身份暴露后更大危机\", \"scene_outcome\": \"阿依莫下令绑人带回村寨说二十年前的事没忘记\"},\n        {\"scene_number\": 2, \"scene_location\": \"村寨边缘木屋，两人被绑坐地上\", \"characters_present\": [\"秦北望\", \"沈屿森\", \"阿依莫\"], \"scene_purpose\": \"揭示冲突表面版本，玉佩成关键道具\", \"core_action\": \"阿依莫审问说他们父辈当年偷圣物伤了她父亲至今瘸腿，沈屿森辩解只是来找遗骨，阿依莫冷笑质疑和想挖宝的人有何区别\", \"conflict_point\": \"僵局阿依莫不信他们说辞\", \"emotional_shift\": \"从被审问无奈转为绝望中挣扎\", \"scene_outcome\": \"秦北望让阿依莫解开领口露出玉佩说是父亲留的\"},\n        {\"scene_number\": 3, \"scene_location\": \"同上气氛骤然凝固\", \"characters_present\": [\"秦北望\", \"沈屿森\", \"阿依莫\"], \"scene_purpose\": \"玉佩身份揭示制造新悬念\", \"core_action\": \"阿依莫扯下玉佩仔细端详表情从愤怒变困惑又变更深疑虑说这是村寨圣物之一当年被偷三件只找回两件为何在他父亲手里\", \"conflict_point\": \"新疑问产生秦守山是偷圣物的人还是另有隐情\", \"emotional_shift\": \"从绝望转为一线转机但真相更扑朔\", \"scene_outcome\": \"阿依莫说今晚留下明天带去见她父亲老头人会说真相\"}\n    ],\n    \"emotional_tone\": \"紧张、对峙、悬念\"\n}\nact_two[\"key_chapters\"].append(ch8)\n\n# 第9章\nch9 = {\n    \"chapter_number\": 9,\n    \"chapter_title\": \"裂痕\",\n    \"chapter_synopsis\": \"夜晚两人被关一起爆发最严重冲突（起始：被软禁焦虑）。秦北望质问如果沈怀瑾执念害死秦守山怎么办，沈屿森反驳父亲笔记记载。两人各执一词互相指责不欢而散（结束状态：关系跌入谷底）\",\n    \"scene_sequence\": [\n        {\"scene_number\": 1, \"scene_location\": \"村寨边缘木屋内，夜晚只有一盏油灯\", \"characters_present\": [\"秦北望\", \"沈屿森\"], \"scene_purpose\": \"积压情绪总爆发两人关系最低点\", \"core_action\": \"秦北望坐角落抽烟沉默，沈屿森试图打破僵局说至少离真相更近，秦北望打断问是不是你爸非要找古城硬拉我爸最后害死他\", \"conflict_point\": \"秦北望把愤怒转向沈屿森和沈怀瑾\", \"emotional_shift\": \"从压抑沉默转为愤怒爆发\", \"scene_outcome\": \"沈屿森也怒了说笔记写清楚是第三个人惹祸\"},\n        {\"scene_number\": 2, \"s